  1	<!doctype html>
  2	<html lang="ru">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Монетка</title>
  7	<style>
  8	  :root { color-scheme: light dark; --accent: #2563eb; --win: #16a34a; --lose: #dc2626; --muted: #6b7280; }
  9	  * { box-sizing: border-box; }
 10	  body { margin: 0; font-family: system-ui, sans-serif; background: Canvas; color: CanvasText; }
 11	  main { max-width: 420px; margin: 0 auto; padding: 24px 16px; display: grid; gap: 16px; }
 12	  h1 { margin: 0; font-size: 24px; }
 13	  .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
 14	  .label { color: var(--muted); font-size: 14px; }
 15	  .balance { font-size: 20px; font-weight: 600; }
 16	  input { font: inherit; padding: 8px; width: 100px; }
 17	  button { font: inherit; padding: 10px 16px; border-radius: 8px; border: 1px solid var(--muted); background: transparent; color: inherit; cursor: pointer; }
 18	  button[aria-pressed="true"] { border-color: var(--accent); background: var(--accent); color: #fff; }
 19	  button:disabled { opacity: .5; cursor: default; }
 20	  #play { background: var(--accent); color: #fff; border-color: var(--accent); width: 100%; font-weight: 600; }
 21	  .coin { width: 120px; height: 120px; margin: 0 auto; border-radius: 50%; display: grid; place-items: center;
 22	          border: 4px solid #ca8a04; background: #facc15; color: #713f12; font-size: 18px; font-weight: 700; }
 23	  [data-state="playing"] .coin { animation: spin .4s linear infinite; }
 24	  @keyframes spin { from { transform: rotateY(0); } to { transform: rotateY(360deg); } }
 25	  .result { text-align: center; min-height: 1.5em; }
 26	  [data-state="won"] .result { color: var(--win); }
 27	  [data-state="lost"] .result { color: var(--lose); }
 28	  .error { color: var(--lose); min-height: 1.2em; }
 29	</style>
 30	</head>
 31	<body>
 32	<main data-testid="game" data-state="idle">
 33	  <h1>Монетка</h1>
 34	  <div class="row"><span class="label">Баланс:</span> <span class="balance" data-testid="balance">—</span></div>
 35	
 36	  <div class="row">
 37	    <label class="label" for="bet">Ставка</label>
 38	    <input id="bet" data-testid="bet-input" type="number" step="0.01" min="1" max="10" value="1">
 39	    <span class="label" id="limits"></span>
 40	  </div>
 41	
 42	  <div class="row" role="group" aria-label="Сторона">
 43	    <button type="button" data-testid="side-heads" data-side="heads" aria-pressed="true">Орёл</button>
 44	    <button type="button" data-testid="side-tails" data-side="tails" aria-pressed="false">Решка</button>
 45	  </div>
 46	
 47	  <button type="button" id="play" data-testid="play">Бросить</button>
 48	
 49	  <div class="coin" data-testid="outcome" aria-live="polite"></div>
 50	  <div class="result">Выплата: <span data-testid="payout">—</span></div>
 51	  <div class="error" data-testid="error" role="alert"></div>
 52	</main>
 53	<script src="/sdk.js"></script>
 54	<script>
 55	(function () {
 56	  'use strict';
 57	
 58	  var SIDE_NAMES = { heads: 'Орёл', tails: 'Решка' };
 59	  var ERROR_TEXT = {
 60	    BET_OUT_OF_LIMITS: 'Ставка вне лимитов',
 61	    INSUFFICIENT_FUNDS: 'Недостаточно средств',
 62	    INVALID_PARAMS: 'Неверные параметры',
 63	    NETWORK_ERROR: 'Нет связи с сервером',
 64	  };
 65	  var started = false;
 66	
 67	  function init() {
 68	    if (started) return;
 69	    started = true;
 70	
 71	    var sdk = window.PlatformSDK;
 72	    var q = function (id) { return document.querySelector('[data-testid="' + id + '"]'); };
 73	    var root = q('game');
 74	    var balanceEl = q('balance');
 75	    var betInput = q('bet-input');
 76	    var playBtn = q('play');
 77	    var outcomeEl = q('outcome');
 78	    var payoutEl = q('payout');
 79	    var errorEl = q('error');
 80	    var limitsEl = document.getElementById('limits');
 81	    var sideButtons = [q('side-heads'), q('side-tails')];
 82	    var side = 'heads';
 83	    var busy = false;
 84	
 85	    function money(n) { return Number(n).toFixed(2); }
 86	    function setState(s) { root.setAttribute('data-state', s); }
 87	    function setBalance(b) { if (typeof b === 'number') balanceEl.textContent = money(b); }
 88	
 89	    function showError(e) {
 90	      var code = (e && e.code) || 'INTERNAL_ERROR';
 91	      var text = ERROR_TEXT[code] || (e && e.message) || 'Ошибка';
 92	      errorEl.textContent = code + ': ' + text;
 93	    }
 94	
 95	    function showRound(round) {
 96	      var view = round && round.view;
 97	      if (!view || !view.outcome) return;
 98	      outcomeEl.textContent = SIDE_NAMES[view.outcome] || view.outcome;
 99	      payoutEl.textContent = money(round.payout || 0);
100	      setState(view.win ? 'won' : 'lost');
101	    }
102	
103	    function selectSide(s) {
104	      side = s;
105	      sideButtons.forEach(function (b) {
106	        b.setAttribute('aria-pressed', b.getAttribute('data-side') === s ? 'true' : 'false');
107	      });
108	    }
109	
110	    function setBusy(v) {
111	      busy = v;
112	      playBtn.disabled = v;
113	      sideButtons.forEach(function (b) { b.disabled = v; });
114	    }
115	
116	    sideButtons.forEach(function (b) {
117	      b.addEventListener('click', function () { if (!busy) selectSide(b.getAttribute('data-side')); });
118	    });
119	
120	    playBtn.addEventListener('click', function () {
121	      if (busy) return;
122	      var bet = Number(betInput.value);
123	      errorEl.textContent = '';
124	      outcomeEl.textContent = '';
125	      payoutEl.textContent = '—';
126	      setBusy(true);
127	      setState('playing');
128	      sdk.startRound(bet, { side: side }).then(function (round) {
129	        setBalance(round.balance);
130	        showRound(round);
131	      }, function (e) {
132	        showError(e);
133	        // Раунд не состоялся: прошлый исход уже стёрт, возвращаемся к ожиданию броска.
134	        setState('idle');
135	      }).then(function () { setBusy(false); });
136	    });
137	
138	    setBusy(true);
139	    sdk.open().then(function (info) {
140	      setBalance(info.balance);
141	      if (info.limits) {
142	        betInput.min = String(info.limits.min);
143	        betInput.max = String(info.limits.max);
144	        limitsEl.textContent = 'от ' + info.limits.min + ' до ' + info.limits.max;
145	      }
146	      // Раунд «Монетки» закрывается в том же запросе, но если платформа вернула раунд — показываем его.
147	      if (info.activeRound) {
148	        if (info.activeRound.view && info.activeRound.view.side) selectSide(info.activeRound.view.side);
149	        showRound(info.activeRound);
150	      }
151	    }, showError).then(function () { setBusy(false); });
152	  }
153	
154	  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
155	  else init();
156	})();
157	</script>
158	</body>
159	</html>

