1	// @vitest-environment happy-dom
2	// Интерфейс «Монетки» (games/coin/spec.md, SC-11): ui/index.html с подменённым window.PlatformSDK.
3	// Внешний /sdk.js не загружается; инлайновые скрипты страницы выполняются в глобальной области, как обычный <script>.
4	import { readFileSync } from 'node:fs';
5	import { dirname, resolve } from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	import { describe, expect, it, vi } from 'vitest';
8	
9	// Строка import.meta.url, а не new URL(): в happy-dom глобальный URL принадлежит окну, а не Node.
10	const HTML_PATH = resolve(dirname(fileURLToPath(import.meta.url)), '../ui/index.html');
11	
12	/** Ждёт выполнения условия, прокручивая очередь задач. */
13	async function waitFor(cond: () => boolean, what: string, timeoutMs = 3000): Promise<void> {
14	  const started = Date.now();
15	  while (!cond()) {
16	    if (Date.now() - started > timeoutMs) throw new Error(`не дождались: ${what}`);
17	    await new Promise((r) => setTimeout(r, 5));
18	  }
19	}
20	
21	const $ = (id: string): HTMLElement => {
22	  const el = document.querySelector(`[data-testid="${id}"]`) as HTMLElement | null;
23	  if (!el) throw new Error(`нет элемента data-testid="${id}"`);
24	  return el;
25	};
26	
27	/** Первое число в тексте элемента (запятая как десятичный разделитель допускается). */
28	const numberIn = (id: string): number => {
29	  const m = ($(id).textContent ?? '').replace(/\s/g, '').replace(',', '.').match(/-?\d+(\.\d+)?/);
30	  return m ? Number(m[0]) : NaN;
31	};
32	
33	const isDisabled = (el: HTMLElement): boolean =>
34	  (el as HTMLButtonElement).disabled === true || el.getAttribute('aria-disabled') === 'true';
35	
36	function deferred<T>() {
37	  let resolve!: (v: T) => void;
38	  let reject!: (e: unknown) => void;
39	  const promise = new Promise<T>((res, rej) => {
40	    resolve = res;
41	    reject = rej;
42	  });
43	  return { promise, resolve, reject };
44	}
45	
46	/** «Открывает» страницу: разметка без <script>, затем подмена SDK, затем инлайновые скрипты. */
47	function loadPage(sdk: unknown): void {
48	  const html = readFileSync(HTML_PATH, 'utf8');
49	  const scripts: string[] = [];
50	  const stripped = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (_m, attrs: string, code: string) => {
51	    if (!/\bsrc\s*=/.test(attrs) && code.trim()) scripts.push(code);
52	    return '';
53	  });
54	  const doc = new DOMParser().parseFromString(stripped, 'text/html');
55	  for (const a of Array.from(doc.documentElement.attributes)) document.documentElement.setAttribute(a.name, a.value);
56	  for (const a of Array.from(doc.body.attributes)) document.body.setAttribute(a.name, a.value);
57	  document.head.innerHTML = doc.head.innerHTML;
58	  document.body.innerHTML = doc.body.innerHTML;
59	
60	  const g = globalThis as any;
61	  g.window.PlatformSDK = sdk;
62	  g.PlatformSDK = sdk;
63	  const indirectEval: (code: string) => unknown = g.eval;
64	  for (const code of scripts) indirectEval(code);
65	  document.dispatchEvent(new g.Event('DOMContentLoaded'));
66	  g.window.dispatchEvent(new g.Event('load'));
67	}
68	
69	describe('Монетка: интерфейс', () => {
70	  it('SC-11: idle → playing → won, затем отказ платформы показывается без смены баланса', async () => {
71	    const pending = deferred<any>();
72	    const sdk = {
73	      open: vi.fn(async () => ({ gameId: 'coin', balance: 100, limits: { min: 1, max: 10 }, activeRound: null })),
74	      startRound: vi.fn((_bet: unknown, _params: unknown) => pending.promise),
75	      action: vi.fn(async () => {
76	        throw { code: 'ROUND_NOT_FOUND', message: 'нет раунда' };
77	      }),
78	    };
79	    loadPage(sdk);
80	
81	    // Загрузка: idle, баланс из open(), ставка по умолчанию 1, выбран орёл.
82	    await waitFor(() => sdk.open.mock.calls.length > 0 && numberIn('balance') === 100, 'баланс 100 после open()');
83	    expect($('game').getAttribute('data-state')).toBe('idle');
84	    expect(Number(($('bet-input') as HTMLInputElement).value)).toBe(1);
85	    expect($('side-heads').getAttribute('aria-pressed')).toBe('true');
86	    expect($('side-tails').getAttribute('aria-pressed')).not.toBe('true');
87	
88	    // Выбор решки.
89	    $('side-tails').click();
90	    expect($('side-tails').getAttribute('aria-pressed')).toBe('true');
91	    expect($('side-heads').getAttribute('aria-pressed')).not.toBe('true');
92	
93	    // Бросок: пока запрос в пути — playing, кнопка заблокирована.
94	    $('play').click();
95	    await waitFor(() => sdk.startRound.mock.calls.length === 1, 'вызов startRound');
96	    expect(sdk.startRound).toHaveBeenCalledWith(1, { side: 'tails' });
97	    await waitFor(() => $('game').getAttribute('data-state') === 'playing', 'data-state=playing');
98	    expect(isDisabled($('play'))).toBe(true);
99	    // Пока ответа нет, исход и выплата не показаны.
100	    expect($('outcome').textContent ?? '').not.toMatch(/Решка|Орёл/);
101	
102	    pending.resolve({
103	      roundId: 'round-1',
104	      gameId: 'coin',
105	      bet: 1,
106	      status: 'closed',
107	      payout: 1.96,
108	      balance: 100.96,
109	      view: { side: 'tails', outcome: 'tails', win: true },
110	    });
111	    await waitFor(() => $('game').getAttribute('data-state') === 'won', 'data-state=won');
112	    expect($('outcome').textContent).toContain('Решка');
113	    expect(numberIn('payout')).toBe(1.96);
114	    expect(numberIn('balance')).toBe(100.96);
115	    await waitFor(() => !isDisabled($('play')), 'кнопка play доступна после броска');
116	
